export const RPE_MIN = 1.0;
export const RPE_MAX = 10.0;
export const REPS_MAX = 45;

/**
 * RPE + ripetizioni -> %1RM, dalla Tabella RPE di Nicolo (unica fonte, regola OS).
 * - rpe: agganciato a [1,10] e arrotondato al passo 0.5 (le righe della tabella).
 * - reps: arrotondate all'intero e agganciate a [1,45] (colonne della tabella).
 * Ritorna il %1RM (0-100). Fuori dai limiti = valore di bordo (nessuna estrapolazione).
 */
export function percent1RM(rpe: number, reps: number): number {
  const r = Math.min(RPE_MAX, Math.max(RPE_MIN, Math.round(rpe * 2) / 2));
  const key = r.toFixed(1);
  const col = Math.min(REPS_MAX, Math.max(1, Math.round(reps)));
  const row = RPE_PERCENT_TABLE[key];
  if (!row) throw new Error(`RPE fuori tabella: ${rpe} -> ${key}`);
  return row[col - 1];
}
